 const render=()=>{const item=images[index];picture.src=mediaURL(item);picture.alt=item.name||item.label||'完整图片';caption.textContent=item.label||item.name||'完整图片';position.textContent=`${index+1} / ${images.length}`;previous.hidden=next.hidden=images.length<2;layout();};
 const move=step=>{index=(index+step+images.length)%images.length;render();};
 bar.append(caption,dimensions,position,button('关闭',()=>dialog.close()));dialog.append(bar,picture,previous,next);
